arguments.command:
for b in rachel monica phoebe joey chandler ross; do echo "=== $b ==="; git log origin/friend/$b --format='%H%n%B' --grep='Friend-Message: 1' | grep -A? ; done >/dev/null 2>&1; python3 - <<'PY'
import subprocess
for b in ['rachel','monica','phoebe','joey','chandler','ross']:
    out=subprocess.check_output(['git','log',f'origin/friend/{b}','--format=%H%x1f%B%x1e'], text=True)
    n=0
    for rec in out.split('\x1e'):
        if 'Friend-Message: 1' in rec and 'Episode: S05/E18' in rec:
            n+=1
    print(b,n)
PY
